// 'Is R360?' persona detection — port of Zap node 339756040, see §9.1
// Case-sensitive String.includes() at 3 nested locations
let data = $json.GPT;
if (typeof data === 'string') {
  try { data = JSON.parse(data); }
  catch (e) { return [{ json: { result: 'False', match: false, error: 'Invalid JSON' } }]; }
}
if (!data) data = $json.body || $json;
let isRena = false;

// Location 1: top-level user_info nicknames
const summaryNickname = data?.user_info?.ids?.agent_nickname || data?.user_info?.agent_nickname;
if (summaryNickname && (summaryNickname.includes('Rena Record') || summaryNickname.includes('Rosie'))) {
  isRena = true;
}

// Location 2: items[*].nickname (loop)
if (!isRena && Array.isArray(data.items)) {
  isRena = data.items.some(item =>
    item.nickname && (item.nickname.includes('Rena') || item.nickname.includes('Rosie'))
  );
}

// Location 3: parse output_text — FLAGGED UNRELIABLE, validate live before cutover
if (!isRena && data.output_text) {
  try {
    const nested = JSON.parse(data.output_text);
    const nickname = nested?.user_info?.ids?.agent_nickname;
    if (nickname && (nickname.includes('Rena Record') || nickname.includes('Rosie'))) {
      isRena = true;
    }
  } catch (e) {
    if (data.output_text.includes('Rena') || data.output_text.includes('Rosie')) isRena = true;
  }
}

return [{ json: { ...$json, result: isRena ? 'True' : 'False', match: isRena, raw: data } }];

// Compute idempotency hash for bot conversation
const crypto = require('crypto');
const entryId = String($json.wpformsEntryId || '');
const hash = crypto.createHash('sha256').update(`bot_r360:${entryId}`).digest('hex');
return [{ json: { ...$json, Idempotency_Hash__c: hash, Received_At__c: new Date().toISOString(), Payload__c: JSON.stringify($json).substring(0, 32000) } }];
